def max_permutation_value(N):
    if N == 1:
        return 0
    if N % 2 == 0:
        return (N // 2) * (N // 2)
    else:
        middle = N // 2 + 1
        return (N // 2) * (N // 2) + middle

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    results = []
    for i in range(1, T + 1):
        N = int(data[i])
        results.append(max_permutation_value(N))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
